export const ZENITH_TEMPLAR_V2_DEF = {grid:ZENITH_TEMPLAR_V2_GRID,materials:ZENITH_TEMPLAR_V2_MATERIALS,parts:PARTS,
 animate({frame=0,now=0,pose='idle',progress=0,reducedMotion=false,attacking=false,charging=false,hurt=false}={}) {
  if(pose==='dead') return {partStates:{hideParts:true},effects:[]};
  const t=reducedMotion?0:Math.floor(now>0?now/120:frame), i=((t%12)+12)%12;
  const p=Math.max(0,Math.min(1,Number.isFinite(progress)?progress:0));
  let swing=0,guard=0;
  if(!reducedMotion){
   if(attacking||pose==='attack') {const j=Math.min(23,Math.floor(p*24));const partStates={};for(const k of Object.keys(PARTS)) if(k!=='legRight')partStates[k]={frame:ATTACK_OFFSETS[k]+j};return {partStates,effects:[]};}
   if(charging||pose==='charge') {swing=Math.min(4,Math.floor(p*5));guard=3;}
   else if(hurt||pose==='hurt'){guard=3;swing=10;}
   else {swing=[0,0,11,11,0,0,10,10,0,0,0,0][i];guard=[0,0,1,1,0,0,7,7,0,0,0,0][i];}
   if(pose==='ward'||pose==='guard')guard=3;
  }
  return {partStates:{capeInner:{frame:i},capeOuter:{frame:i},sword:{frame:swing},swordArm:{frame:swing},shield:{frame:guard},shieldArm:{frame:guard}},effects:[]};
 }};
